//! ✂️ Original-bound scalar and UTF8 splice coordinates retain no copied text or style row list.
use crate::LayoutMutation;
use semio_s_artifact_layout_layout_model::{snapshot::LayoutSnapshot,TextStyleRun};
use semio_framework_value::{RetirementDemand,ValueError,ValueRefusalKind,retained_clone::{RetainedCloneRef,RetainedCloneBinding,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits}};
use super::super::target::{LayoutTargetLookup,LayoutTargetSource};
fn fault()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original story splice plan custody is invalid")}
fn fixed()->RetirementDemand{RetirementDemand{copy_bytes:2048,depth:1,..Default::default()}}
fn nested(mut d:RetirementDemand)->RetirementDemand{d.copy_bytes+=2048;d.depth+=1;d}
fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-2048,maximum_depth:g.maximum_depth-1,..g}}
fn receipt(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_items=p.copied_items.max(1);p.copied_bytes+=2048;p}
fn refused(e:ValueError)->ValueError{let p=receipt(e.retained_progress());e.with_retained_progress(p)}
fn payload(m:&LayoutMutation)->Result<&crate::edit_story::EditStory,ValueError>{if let LayoutMutation::EditStory(p)=m{Ok(p)}else{Err(fault())}}
struct Stories<'a>(&'a LayoutSnapshot);impl LayoutTargetSource for Stories<'_>{fn identity(&self)->usize{8801}fn count(&self)->usize{self.0.stories.len()}fn key(&self,i:usize)->&str{&self.0.stories[i].id}}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum StorySpliceFailure{Missing,Range,Overflow}
/// 🧭️ A constant scalar cursor recomputes each original run's three bounded surviving pieces without storing a copied run list.
pub struct StorySplicePlan{m:Option<RetainedCloneBinding>,b:Option<RetainedCloneBinding>,lookup:LayoutTargetLookup,phase:u8,scalar:usize,offset:usize,start:usize,end:usize,insert_scalars:usize,old_length:usize,index:usize,new_count:usize,changed:bool,closing:bool,pub story:usize,pub failure:Option<StorySpliceFailure>,pub unchanged:bool}
impl Default for StorySplicePlan{fn default()->Self{Self{m:None,b:None,lookup:Default::default(),phase:0,scalar:0,offset:0,start:0,end:0,insert_scalars:0,old_length:0,index:0,new_count:0,changed:false,closing:false,story:0,failure:None,unchanged:false}}}
impl StorySplicePlan{
 pub fn ready(&self)->bool{self.phase==20&&!self.closing}pub fn range(&self)->[usize;2]{[self.start,self.end]}pub fn inserted_scalars(&self)->usize{self.insert_scalars}pub fn new_run_count(&self)->usize{self.new_count}pub fn runs_changed(&self)->bool{self.changed}
 pub fn verify(&self,m:RetainedCloneRef<'_,LayoutMutation>,b:RetainedCloneRef<'_,LayoutSnapshot>)->Result<(),ValueError>{if self.closing{return Err(fault())}payload(m.get())?;m.check_binding(&self.m)?;b.check_binding(&self.b)}
 pub fn demand(&self,m:RetainedCloneRef<'_,LayoutMutation>,b:RetainedCloneRef<'_,LayoutSnapshot>)->Result<RetirementDemand,ValueError>{self.verify(m,b)?;Ok(match self.phase{0=>nested(m.binding_demand(&self.m)?.unwrap_or_default()),1=>nested(b.binding_demand(&self.b)?.unwrap_or_default()),2=>nested(self.lookup.demand()),_=>fixed()})}
 pub fn transformed(&self,run:&TextStyleRun,inserted:usize)->Option<Option<[u64;2]>>{let(start,end,inserted,old)=(u64::try_from(self.start).ok()?,u64::try_from(self.end).ok()?,u64::try_from(inserted).ok()?,u64::try_from(self.old_length).ok()?);let middle=start.checked_add(inserted)?;let shift=|at:u64|at.checked_sub(end-start)?.checked_add(inserted);if run.start==run.end{let at=if run.start<start{run.start}else if run.start>=end{shift(run.start)?}else{middle};return Some(Some([at,at]))}let prefix=(run.start<start).then_some((run.start,run.end.min(start)));let inherits=run.start<=start&&start<run.end||start==old&&run.start<start&&run.end==start;let middle=(inherits&&inserted>0).then_some((start,middle));let suffix=if run.end>end{Some((shift(run.start.max(end))?,shift(run.end)?))}else{None};let mut pieces=[prefix,middle,suffix].into_iter().flatten().filter(|(a,b)|a<b);Some(pieces.next().map(|(a,b)|[a,pieces.last().map_or(b,|(_,end)|end)]))}
 pub fn advance(&mut self,m:RetainedCloneRef<'_,LayoutMutation>,b:RetainedCloneRef<'_,LayoutSnapshot>,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(m,b)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}let p=payload(m.get())?;let mut paid=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};match self.phase{0=>{paid=receipt(m.bind(&mut self.m,child(g)).map_err(refused)?.unwrap_or_default());self.phase=1},1=>{paid=receipt(b.bind(&mut self.b,child(g)).map_err(refused)?.unwrap_or_default());self.phase=2},2=>{let step=self.lookup.advance(&Stories(b.get()),8802,&p.id,child(g)).map_err(refused)?;paid=receipt(step.progress());if let Some(found)=self.lookup.result(){if let Some(story)=found{self.story=story;self.old_length=b.get().stories[story].content.len();self.phase=3}else{self.failure=Some(StorySpliceFailure::Missing);self.phase=20}}},3=>{if let Some(end)=p.offset.checked_add(p.delete){let text=&b.get().stories[self.story].content;for n in 0..=64{if self.scalar==p.offset{self.start=self.offset}if self.scalar==end{self.end=self.offset;self.offset=0;self.phase=4;break}if self.offset==text.len(){self.failure=Some(StorySpliceFailure::Range);self.phase=20;break}if n==64{break}let ch=text[self.offset..].chars().next().ok_or_else(fault)?;self.offset+=ch.len_utf8();self.scalar+=1}}else{self.failure=Some(StorySpliceFailure::Range);self.phase=20}},4=>{if self.end-self.start!=p.insert.len(){self.offset=0;self.phase=5}else{let end=p.insert.len().min(self.offset+256);let same=b.get().stories[self.story].content.as_bytes()[self.start+self.offset..self.start+end]==p.insert.as_bytes()[self.offset..end];if !same{self.offset=0;self.phase=5}else{self.offset=end;if end==p.insert.len(){self.unchanged=true;self.phase=20}}}},5=>{for ch in p.insert[self.offset..].chars().take(64){self.offset+=ch.len_utf8();self.insert_scalars+=1}if self.offset==p.insert.len(){self.offset=0;if self.old_length.checked_sub(self.end-self.start).and_then(|n|n.checked_add(p.insert.len())).and_then(|n|u64::try_from(n).ok()).is_none(){self.failure=Some(StorySpliceFailure::Overflow);self.phase=20}else{self.phase=7}}},7=>{let runs=&b.get().stories[self.story].style_runs;if self.index==runs.len(){self.changed|=self.new_count!=runs.len();self.phase=20}else{let run=&runs[self.index];if let Some(next)=self.transformed(run,p.insert.len()){if let Some([a,z])=next{self.new_count+=1;self.changed|=a!=run.start||z!=run.end}else{self.changed=true}self.index+=1}else{self.failure=Some(StorySpliceFailure::Overflow);self.phase=20}}},20=>{},_=>return Err(fault())}Ok(if self.ready(){RetainedCloneStep::Complete(paid)}else{RetainedCloneStep::Progress(paid)})}
 pub fn begin_close(&mut self){self.closing=true;self.lookup.begin_close()}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(fault())}if !self.lookup.terminal_is_empty(){return Ok(nested(self.lookup.close_demand()))}Ok(nested(RetainedCloneBinding::close_demand(if self.b.is_some(){&self.b}else{&self.m},body.min(256))?))}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.lookup.terminal_is_empty(){return self.lookup.close_step(child(g)).map(|s|RetainedCloneStep::Progress(receipt(s.progress()))).map_err(refused)}let p=receipt(RetainedCloneBinding::close_one(if self.b.is_some(){&mut self.b}else{&mut self.m},child(g)).map_err(refused)?.progress());Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.lookup.terminal_is_empty()&&self.b.is_none()&&self.m.is_none()}
}
impl Drop for StorySplicePlan{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original splice numeric plan requires funded cleanup")}}
